import {
  useEffect,
  useMemo,
  useState,
} from "react";

import {
  Box,
  Button,
  Stack,
  Typography,
} from "@mui/material";

import {
  GrainRounded,
  WbTwilightRounded,
  AirRounded,
  CloudRounded,
  OpacityRounded,
  ThermostatRounded,
  UmbrellaRounded,
  WbSunnyRounded,
  WaterDropRounded,
} from "@mui/icons-material";

import {
  useForecastContext,
} from "../../../contexts/ForecastContext";

import {
  useWeatherOutlook,
  useWeatherSignals,
  useWeatherSummary,
} from "../hooks/useWeather";

import {
  WeatherOutlookDay,
} from "../types/weather.types";
import { useForecastEntities } from "../hooks/useForecast";



import {
  SurfaceValue,
  cardBorderColor,
  cardFill,
  infoTint,
  neutralFill,
  softBorder,
  softText,
  successTint,
  warningTint,
} from "../../../theme/surfaces";

interface WeatherIntelligenceProps {
  entityId?: string;
}


type WeatherView =
  | "current"
  | "7"
  | "30";


interface WeatherEntity {
  id: string;
  label?: string;
  name?: string;
}


const WeatherIntelligence = ({
  entityId: propEntityId,
}: WeatherIntelligenceProps) => {

  const {
    entityId:
      contextEntityId,
    setEntityId,
  } = useForecastContext();


  /**
   * IMPORTANT:
   *
   * `entities` should be the dynamically loaded
   * station/entity collection from your existing
   * forecast/entity hook.
   *
   * Keep the same hook/import you already have
   * in your current working version.
   */

  const {
    data: entities = [],
  } = useForecastEntities();


  /**
   * Use prop entityId when supplied.
   * Otherwise use the global forecast context.
   */

  const entityId =
    propEntityId ||
    contextEntityId;


  const [
    view,
    setView,
  ] = useState<WeatherView>(
    "current"
  );


  /**
   * --------------------------------------------------------
   * ENSURE CURRENT ENTITY EXISTS
   * --------------------------------------------------------
   *
   * This MUST be inside useEffect because
   * setEntityId() is a state update.
   */

  useEffect(() => {
    if (entities.length === 0) {
      return;
    }

    const currentEntityExists =
      entities.some(
        (entity: WeatherEntity) =>
          entity.id ===
          contextEntityId
      );

    if (!currentEntityExists) {
      setEntityId(
        entities[0].id
      );
    }
  }, [
    entities,
    contextEntityId,
    setEntityId,
  ]);


  const days =
    view === "30"
      ? 30
      : 7;


  /**
   * --------------------------------------------------------
   * CURRENT WEATHER
   * --------------------------------------------------------
   */

  const {
    data: current,
    isLoading:
      currentLoading,
    isError:
      currentError,
  } =
    useWeatherSummary(
      entityId
    );


  /**
   * --------------------------------------------------------
   * WEATHER OUTLOOK
   * --------------------------------------------------------
   */

  const {
    data: outlook = [],
    isLoading:
      outlookLoading,
    isError:
      outlookError,
  } =
    useWeatherOutlook(
      entityId,
      days
    );


  /**
   * --------------------------------------------------------
   * WEATHER SIGNALS
   * --------------------------------------------------------
   */

  const {
    data: signals,
    isLoading:
      signalsLoading,
  } =
    useWeatherSignals(
      entityId,
      days
    );


  /**
   * --------------------------------------------------------
   * FORMAT NUMBER
   * --------------------------------------------------------
   */

  const formatNumber = (
    value:
      | number
      | null
      | undefined,
    decimals = 1
  ) => {
    if (
      value === null ||
      value === undefined
    ) {
      return "—";
    }

    return value.toFixed(
      decimals
    );
  };


  /**
   * --------------------------------------------------------
   * FORMAT DATE
   * --------------------------------------------------------
   */

  const formatDate = (
    date: string
  ) => {
    const parsed =
      new Date(date);

    if (
      Number.isNaN(
        parsed.getTime()
      )
    ) {
      return date;
    }

    return parsed.toLocaleDateString(
      "en-GB",
      {
        day: "2-digit",
        month: "short",
      }
    );
  };


  /**
   * --------------------------------------------------------
   * DAY NAME
   * --------------------------------------------------------
   */

  const getDayName = (
    date: string
  ) => {
    const parsed =
      new Date(date);

    if (
      Number.isNaN(
        parsed.getTime()
      )
    ) {
      return "";
    }

    return parsed.toLocaleDateString(
      "en-US",
      {
        weekday: "short",
      }
    );
  };


  /**
   * --------------------------------------------------------
   * WEATHER ICON
   * --------------------------------------------------------
   */

  const getWeatherIcon = (
    condition:
      | string
      | null
      | undefined
  ) => {

    const text =
      (
        condition ?? ""
      ).toLowerCase();


    if (
      text.includes("rain") ||
      text.includes("shower") ||
      text.includes("drizzle")
    ) {
      return (
        <UmbrellaRounded />
      );
    }


    if (
      text.includes("cloud") ||
      text.includes("overcast")
    ) {
      return (
        <CloudRounded />
      );
    }


    if (
      text.includes("sun") ||
      text.includes("clear")
    ) {
      return (
        <WbSunnyRounded />
      );
    }


    return (
      <CloudRounded />
    );
  };


  /**
   * --------------------------------------------------------
   * CURRENT TEMPERATURE
   * --------------------------------------------------------
   */

  const currentTemperature =
    useMemo(() => {

      if (!current) {
        return null;
      }

      return (
        current.tempMax ??
        current.tempMin
      );

    }, [current]);


  const loading =
    currentLoading ||
    outlookLoading ||
    signalsLoading;


  const error =
    currentError ||
    outlookError;


  return (
    <Box
      sx={{
        width: "100%",
        height: "100%",
        bgcolor: cardFill,
        border: "1px solid",
        borderColor: cardBorderColor,
        borderRadius:
          "12px !important",
        p: {
          xs: 2.5,
          md: 3,
        },
        boxSizing:
          "border-box",
        overflow: "auto",
        maxHeight: {
          xs: "auto",
          xl: "900px",
        },
        boxShadow: (t) =>
          t.palette.mode === "dark"
            ? "0 10px 30px rgba(0,0,0,0.4)"
            : "0 10px 30px rgba(16,32,62,0.06)",
      }}
    >

      {/* HEADER */}

      <Stack
        direction="column"
        spacing={2}
        alignItems="flex-start"
        sx={{
          minWidth: 0,
          overflow: "hidden",
          mb: 2,
        }}
      >

        <Stack
          direction={{
            xs: "column",
            sm: "row",
          }}
          spacing={2}
          alignItems={{
            xs: "flex-start",
            sm: "center",
          }}
          justifyContent="space-between"
          sx={{
            width: "100%",
          }}
        >

          <Stack
            direction={{
              xs: "column",
              sm: "row",
            }}
            spacing={2}
            alignItems={{
              xs: "flex-start",
              sm: "center",
            }}
          >

            <Box
              sx={{
                width: 48,
                height: 48,
                borderRadius: "10px",
                bgcolor: infoTint,
                color:
                  "#1264FF",
                display: "flex",
                alignItems:
                  "center",
                justifyContent:
                  "center",
                flexShrink: 0,
              }}
            >
              <CloudRounded
                sx={{
                  fontSize: 28,
                }}
              />
            </Box>


            <Box
              sx={{
                minWidth: 0,
                flex: 1,
              }}
            >

              <Typography
                variant="h6"
                fontWeight={800}
                color="text.primary"
              >
                Weather Intelligence
              </Typography>


              <Typography
                variant="body2"
                color="text.secondary"
                mt={0.5}
                sx={{
                  wordBreak:
                    "break-word",
                  overflowWrap:
                    "break-word",
                }}
              >
                Conditions and outlook
                for{" "}
                <strong>
                  {entityId ||
                    "selected station"}
                </strong>
              </Typography>

            </Box>

          </Stack>

        </Stack>


        {/* VIEW TOGGLE */}

        <Stack
          direction="row"
          spacing={1}
          sx={{
            flexShrink: 0,
            width: {
              xs: "100%",
              sm: "auto",
            },
          }}
        >

          <Button
            onClick={() =>
              setView("current")
            }
            variant={
              view === "current"
                ? "contained"
                : "outlined"
            }
            size="small"
            sx={{
              textTransform:
                "none",
              fontWeight: 700,
              minWidth: {
                xs: "auto",
                sm: 90,
              },
              flex: {
                xs: 1,
                sm: "0 0 auto",
              },
              borderRadius: "8px",
            }}
          >
            Current
          </Button>


          <Button
            onClick={() =>
              setView("7")
            }
            variant={
              view === "7"
                ? "contained"
                : "outlined"
            }
            size="small"
            sx={{
              textTransform:
                "none",
              fontWeight: 700,
              minWidth: {
                xs: "auto",
                sm: 90,
              },
              flex: {
                xs: 1,
                sm: "0 0 auto",
              },
              borderRadius: "8px",
            }}
          >
            7 Days
          </Button>


          <Button
            onClick={() =>
              setView("30")
            }
            variant={
              view === "30"
                ? "contained"
                : "outlined"
            }
            size="small"
            sx={{
              textTransform:
                "none",
              fontWeight: 700,
              minWidth: {
                xs: "auto",
                sm: 90,
              },
              flex: {
                xs: 1,
                sm: "0 0 auto",
              },
              borderRadius: "8px",
            }}
          >
            30 Days
          </Button>

        </Stack>

      </Stack>


      <Box
        sx={{
          borderTop:
            "1px solid",
          borderColor:
            "divider",
          my: 2,
        }}
      />


      {/* CURRENT VIEW */}

      {view === "current" && (
        <CurrentWeather
          current={current}
          temperature={
            currentTemperature
          }
          loading={
            currentLoading
          }
          error={
            currentError
          }
          formatNumber={
            formatNumber
          }
          formatDate={
            formatDate
          }
          getWeatherIcon={
            getWeatherIcon
          }
        />
      )}


      {/* OUTLOOK VIEW */}

      {view !== "current" && (
        <>
          {error ? (
            <Typography
              color="error"
              py={4}
            >
              Unable to load the
              weather outlook.
            </Typography>
          ) : loading ? (
            <Typography
              color="text.secondary"
              py={4}
            >
              Loading weather outlook...
            </Typography>
          ) : (
            <>
              <WeatherOutlookGrid
                records={outlook}
                formatNumber={
                  formatNumber
                }
                formatDate={
                  formatDate
                }
                getDayName={
                  getDayName
                }
                getWeatherIcon={
                  getWeatherIcon
                }
              />

              <WeatherSignals
                signals={signals}
                formatNumber={
                  formatNumber
                }
              />
            </>
          )}
        </>
      )}

    </Box>
  );
};


/* =========================================================
   CURRENT WEATHER
========================================================= */

interface CurrentWeatherProps {
  current:
    | {
        condition: string;
        tempMax:
          | number
          | null;
        tempMin:
          | number
          | null;
        rainfall:
          | number
          | null;
        cloudCover:
          | number
          | null;
        humidity:
          | number
          | null;
        windSpeed:
          | number
          | null;
        uvIndex:
          | number
          | null;
        sunshine:
          | number
          | null;
        date: string;
      }
    | null
    | undefined;

  temperature:
    | number
    | null;

  loading: boolean;

  error: boolean;

  formatNumber: (
    value:
      | number
      | null
      | undefined,
    decimals?: number
  ) => string;

  formatDate: (
    value: string
  ) => string;

  getWeatherIcon: (
    condition:
      | string
      | null
      | undefined
  ) => React.ReactNode;
}


const CurrentWeather = ({
  current,
  temperature,
  loading,
  error,
  formatNumber,
  formatDate,
  getWeatherIcon,
}: CurrentWeatherProps) => {

  if (loading) {
    return (
      <Typography
        color="text.secondary"
      >
        Loading current weather...
      </Typography>
    );
  }


  if (error || !current) {
    return (
      <Typography
        color="text.secondary"
      >
        No current weather data is
        available for this entity.
      </Typography>
    );
  }


  const items = [
    {
      label: "Condition",
      value:
        current.condition,
      icon:
        getWeatherIcon(
          current.condition
        ),
    },
    {
      label: "High / Low",
      value: `${formatNumber(
        current.tempMax
      )} °C / ${formatNumber(
        current.tempMin
      )} °C`,
      icon:
        <ThermostatRounded />,
    },
    {
      label: "Rainfall",
      value: `${formatNumber(
        current.rainfall
      )} mm`,
      /* rain drops — distinct from the humidity water drop */
      icon:
        <GrainRounded />,
    },
    {
      label: "Cloud Cover",
      value: `${formatNumber(
        current.cloudCover,
        0
      )}%`,
